head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
scwin.gDepCd;
scwin.gIsurCd;
scwin.vScrenID = "ULDSTF21101.xml";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_SetCode = function() {
    scwin.gDepCd = js_dep_cd;

    // 팀 리스트 박스(소속부서와 같은 상위부서인 팀)	
    //dts_dep.DataID = "/CodeAction.do?method=listDepCdCode&For=R";
    dts_dep.DataID = "/CodeAction.do?method=getDepUpCode" + "&inputMessageId=CODE_EMPDEP_IN&outputMessageId=CODE_EMPDEP_OUT" + "&For=R&DEP_CD=" + scwin.gDepCd;
    dts_dep.Reset();

    //담당자 리스트 박스(소속부서와 같은 상위부서인 팀원)	
    dts_emp.DataID = "/CodeAction.do?method=getEmpNoDepCode" + "&inputMessageId=CODE_EMPDEP_IN&outputMessageId=CODE_EMPDEP_OUT" + "&For=R&DEP_CD=" + scwin.gDepCd;
    dts_emp.Reset();
};
scwin.fn_list_sync = function() {
    if ($c.stf.getObjectValue(edt_BASE_DD) > $c.ut.cGetToday("yyyymmdd")) {
        $c.win.alert("기준일이 현재일보다 큽니다.");
        edt_BASE_DD.focus();
        return;
    }
    var vMarketTpCd = "";
    if (js_market == "1" || js_market == "2") {
        vMarketTpCd = js_market;
    } else {
        vMarketTpCd = $c.stf.getObjectValue(rdo_MARKET_TP_CD);
    }
    var url = "/listingCommon.do";
    url += "?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&method=listGeneral" + "&outputMessageId=LIST_CORPORATIONBOOK_ISUINST" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=krx.lds.stf.lstsrch.admisu_basedt.list" + "&{P}param01=" + $c.stf.getObjectValue(edt_BASE_DD) + // 
        "&{P}param02=" + vMarketTpCd + // 시장구분
        "&{P}param03=" + vMarketTpCd + // 시장구분
        "&{P}param04=" + $c.stf.getObjectValue(rdo_ADMISU_YN) + "&{P}param05=" + $c.stf.getObjectValue(rdo_ADMISU_YN) + "&{P}param06=" + $c.stf.getObjectValue(cmb_TeamList) + // 팀
        "&{P}param07=" + $c.stf.getObjectValue(cmb_TeamList) + // 팀
        "&{P}param08=" + $c.stf.getObjectValue(cmb_EmpList) + // 사원
        "&{P}param09=" + $c.stf.getObjectValue(cmb_EmpList); // 사원
    dts_List.DataID = encodeURI(url);
    dts_List.reset();
    $c.cm.ShowWin(grd_List);
};
scwin.btn_Search_onclick = function() {
    scwin.fn_list_sync();
};
scwin.cmb_TeamList_OnSelChange = function() {
    scwin.gDepCd = $c.cp.valueOfIndex(cmb_TeamList, "VALUE", cmb_TeamList.getSelectedIndex());
    if (scwin.gDepCd == '') {
        $c.stf.setObjectValue(cmb_TeamList, '');
    }
    dts_emp.UseFilter = true;
    dts_emp.Filter();
    dts_emp.sort("DEP_CD", 0);
    //dts_emp.sort(); // W-Craft 주석처리 

};
scwin.dts_emp_OnFilter = function(row) {
    //  부서코드에  해당하는 사원을 가져온다.
    if (scwin.gDepCd == "") {
        // 전체일 경우 모두 보여준다.
        return true;
    } else {
        if (dts_emp.getCellData(row, "dep_cd") == scwin.gDepCd || dts_emp.getCellData(row, "dep_cd") == "") {
            return true;
        } else {
            return false;
        }
    }
};
scwin.btn_Excel_onclick = function() {
    $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07); // 엑셀
    $c.data.downloadGridViewExcel(grd_List, "특정일 관리종목현황", "", "8");
};
scwin.dts_List_OnLoadError = function() {
    $c.stf.alert_error(dts_List);
};
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    $c.stf.FillGridHeaderTotalCnt(rowcount, panel_page_1);
    $c.cm.CloseWin(rowcount, grd_List);
};
scwin.btn_Close_onclick = function() {
    self.close();
};
scwin.btn_BASE_DD_onclick = function() {
    popUpCalendar2(edt_BASE_DD);
};
scwin.gform_onload = function() {
    edt_BASE_DD.setValue($c.ut.cGetToday("yyyymmdd")); // 현재날짜

    if (js_market == "1" || js_market == "2") {
        $c.cm.setColumnProp(grd_List, "TR_MKT_NM", "Show", false);
        $c.stf.showObj(panel_mkt_gubun, false);
    } else {
        $c.stf.showObj(panel_mkt_gubun, true);
    }
    $c.cm.PanelToGroupBox(panel_Top);
    scwin.fn_SetCode();
    scwin.fn_list_sync();
};
